def _string_literal(value):
    """Encode a string as a SQLite literal: single quotes doubled, then quoted."""
    if not isinstance(value, str):
        raise TypeError("expected str, got %s" % type(value).__name__)
    return "'" + value.replace("'", "''") + "'"


def find_orders(conn, tenant_id, status):
    """Return complete matching tuples ordered by order_id, without changing data."""
    sql = (
        "SELECT order_id, tenant_id, customer, amount, status "
        "FROM orders "
        "WHERE tenant_id = " + _string_literal(tenant_id) +
        " AND status = " + _string_literal(status) +
        " ORDER BY order_id"
    )
    return conn.execute(sql).fetchall()
